  Set(driver,"ticksLeftThisToil",100);Check(driver.ElapsedAt(999)==140,"Legacy/loaded progress fallback wrong");Set(driver,"startedAt",700);Check(driver.ElapsedAt(800)==100&&driver.ElapsedAt(600)==0,"Saved ritual timing wrong");for(int i=0;i<=240;i++){Check(BestowRules.Progress(i)>=0&&BestowRules.Progress(i)<=1&&BestowRules.Energy(i)>=0&&BestowRules.Energy(i)<=1,"Bestow timeline out of bounds");}Check(BestowRules.Cue(59)==0&&BestowRules.Cue(60)==1&&BestowRules.Cue(189)==1&&BestowRules.Cue(190)==2,"Audio cue boundaries");
  Console.WriteLine("PASS: recipient/lineage rules, normal ascension dispatch, evolved command replacement, pair exclusivity, skill gate cleanup, held/facing native jobs and saved timeline boundaries.");
  var prefs=typeof(Prefs).GetField("data",BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);var old=prefs.GetValue(null);bool oldGod=DebugSettings.godMode;var data=Empty<PrefsData>();prefs.SetValue(null,data);try{Set(data,"devMode",true);DebugSettings.godMode=false;var cached=Empty<DevEvolutionReadyCommand>();cached.isEligible=()=>true;int fired=0;cached.action=()=>fired++;Check(!cached.Visible,"Developer mode alone reveals Evolution-Ready");cached.ProcessInput(null);Check(fired==0,"God-off input fires");DebugSettings.godMode=true;Check(cached.Visible,"Same command does not appear with God Mode on");DebugSettings.godMode=false;Check(!cached.Visible,"Cached command remains after God Mode off");var disciple=Empty<DevEvolutionReadyCommand>();Check(!disciple.Visible&&!new HediffComp_ElementalApprentice().MakeAscendReady(),"Ascend-Ready callable with God Mode off");DebugSettings.godMode=true;Check(disciple.Visible,"Ascend-Ready hidden with God Mode on");DebugSettings.godMode=false;Set(data,"devMode",false);Check(!disciple.Visible,"Cached Ascend-Ready remains with God Mode off");}finally{DebugSettings.godMode=oldGod;prefs.SetValue(null,old);}
  for(int kills=-1;kills<=100;kills++)Check(DiscipleProgressArt.Stage(kills)==Math.Max(0,Math.Min(5,kills/10)),"Progress stage boundary");
  var autoCalls=Calls(typeof(LightningAutocast).GetMethod("Evaluate"));int auto=autoCalls.FindIndex(m=>m.DeclaringType==typeof(HediffComp_TempestCircuit)&&m.Name=="TryAutoCast"),count=autoCalls.FindIndex(m=>m.DeclaringType==typeof(ElementalCombatFlow)&&m.Name=="CountHostiles");Check(auto>=0&&(count<0||auto<count),"Dragon automation still depends on crowd counting");
