  Console.WriteLine("PASS: 10,000 Bestow registrations retain fixed buffers; native save output retains ritual start/cue/commitment and disciple kills.");Console.WriteLine("LIMIT: full live ascension application, native loading, actual paired facing and GPU garment/effect rendering remain in-game checks.");
 }
